gEL(){return"\u0417\u0430\u043c\u0435\u0442\u043a\u0430"},
gMH(){return"\u0418\u043a\u043e\u043d\u043a\u0430"},
gKG(){return"\u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f"},
