gFR(){return"\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0416\u0435\u043d\u044f"},
gPR(){return"\u0418\u043c\u044f \u0432\u0438\u0434\u043d\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c \u043e\u0431\u0449\u0438\u0445 \u0441\u043f\u0438\u0441\u043a\u043e\u0432: \u043a\u0442\u043e \u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u0441\u043f\u0438\u0441\u043e\u043a \u0438 \u043a\u0442\u043e \u043e\u0442\u043c\u0435\u0442\u0438\u043b \u0442\u043e\u0432\u0430\u0440. \u0425\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u043e\u0431\u043b\u0430\u043a\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0441\u043f\u0438\u0441\u043a\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u0432\u044b \u043f\u043e\u0434\u0435\u043b\u0438\u043b\u0438\u0441\u044c."},
gPS(){return"\u0418\u043c\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e"},
gPC(){return"\u0421\u0435\u0439\u0447\u0430\u0441 \u0441\u043c\u043e\u0442\u0440\u044f\u0442"},
gwG(){return"\u041a\u0442\u043e-\u0442\u043e"},
gyT(){return"\u042f\u0437\u044b\u043a"},
gNv(){return"\u0421\u043f\u0438\u0441\u043a\u0438"},
gNx(){return"\u041f\u043e\u043a\u0443\u043f\u043a\u0438"},
gNu(){return"\u0421\u043e\u0437\u0434\u0430\u0442\u044c"},
gNw(){return"\u041f\u0440\u043e\u0444\u0438\u043b\u044c"},
gOw(){return"\u041f\u0440\u043e\u0444\u0438\u043b\u044c"},
