MR(a,b,c){return"\u041f\u0440\u0438\u0454\u0434\u043d\u0443\u0439\u0441\u044f \u0434\u043e \u043c\u043e\u0433\u043e \u0441\u043f\u0438\u0441\u043a\u0443 \xab"+a+"\xbb \u0443 \u0428\u043e\u043f\u043b\u0438\u0441\u0442\u0456:\n"+b+"\n\n\u042f\u043a\u0449\u043e \u0428\u043e\u043f\u043b\u0438\u0441\u0442 \u0443\u0436\u0435 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e \u2014 \u043c\u0435\u043d\u044e \u22ef \u2192 \xab\u041f\u0440\u0438\u0454\u0434\u043d\u0430\u0442\u0438\u0441\u044f \u0437\u0430 \u043a\u043e\u0434\u043e\u043c\xbb: "+c},
gN3(){return"\u0412\u0438 \u0443 \u0441\u043f\u0456\u043b\u044c\u043d\u043e\u043c\u0443 \u0441\u043f\u0438\u0441\u043a\u0443"},
MS(a){return"\u042f\u043a\u0449\u043e \u0428\u043e\u043f\u043b\u0438\u0441\u0442 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e \u043d\u0430 \u0435\u043a\u0440\u0430\u043d \xab\u0414\u043e\u0434\u043e\u043c\u0443\xbb, \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u0442\u0430 \u0432\u0432\u0435\u0434\u0456\u0442\u044c \u043a\u043e\u0434 \u0442\u0430\u043c: \u043c\u0435\u043d\u044e \u22ef \u2192 \xab\u041f\u0440\u0438\u0454\u0434\u043d\u0430\u0442\u0438\u0441\u044f \u0437\u0430 \u043a\u043e\u0434\u043e\u043c\xbb \u2192 "+a+".\n\nSafari \u0456 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0439 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u044e\u0442\u044c \u0434\u0430\u043d\u0456 \u043e\u043a\u0440\u0435\u043c\u043e \u2014 \u0431\u0435\u0437 \u0446\u044c\u043e\u0433\u043e \u043a\u0440\u043e\u043a\u0443 \u0441\u043f\u0438\u0441\u043e\u043a \u0437\u0430\u043b\u0438\u0448\u0438\u0442\u044c\u0441\u044f \u043b\u0438\u0448\u0435 \u0442\u0443\u0442, \u0443 Safari."},
Lz(a,b){return"\u0421\u043f\u0438\u0441\u043e\u043a \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439: \xab"+a+"\xbb \u0456 \u0432\u0441\u0456 \u0439\u043e\u0433\u043e \u0442\u043e\u0432\u0430\u0440\u0438 \u0437\u043d\u0438\u043a\u043d\u0443\u0442\u044c \u0443 \u0412\u0421\u0406\u0425 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 ("+b+"), \u043d\u0435 \u043b\u0438\u0448\u0435 \u0443 \u0432\u0430\u0441."},
