gO0(){return"\u0412\u0456\u0447\u043d\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a"},
gO_(){return"\u0421\u043f\u0438\u0441\u043e\u043a \u2014 \u0432\u0430\u0448 \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0438\u0439 \u043a\u0430\u0442\u0430\u043b\u043e\u0433 \u0442\u043e\u0432\u0430\u0440\u0456\u0432, \u0432\u0456\u043d \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043e\u0447\u0438\u0449\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0435\u0440\u0435\u0434 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u043e\u043c \u043f\u043e\u0437\u043d\u0430\u0447\u0430\u0454\u0442\u0435, \u0449\u043e \u0442\u0440\u0435\u0431\u0430 \u043a\u0443\u043f\u0438\u0442\u0438, \u2014 \u0440\u0435\u0448\u0442\u0430 \u0441\u043f\u043e\u043a\u0456\u0439\u043d\u043e \u0447\u0435\u043a\u0430\u0454 \u0441\u0432\u043e\u0433\u043e \u0447\u0430\u0441\u0443."},
gO2(){return"\u041e\u0434\u0438\u043d \u0442\u0430\u043f \u2014 \u043e\u0434\u043d\u0430 \u0434\u0456\u044f"},
gO1(){return"\u0422\u0430\u043f \u043f\u043e \u0442\u043e\u0432\u0430\u0440\u0443: \xab\u0434\u043e \u043f\u043e\u043a\u0443\u043f\u043a\u0438\xbb \u2192 \xab\u043a\u0443\u043f\u043b\u0435\u043d\u043e\xbb (\u043f\u0435\u0440\u0435\u043a\u0440\u0435\u0441\u043b\u0435\u043d\u0438\u0439, \u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u043c\u0456\u0441\u0446\u0456). \u0414\u043e\u0432\u0433\u0435 \u043d\u0430\u0442\u0438\u0441\u043a\u0430\u043d\u043d\u044f \u2014 \u0437\u043d\u044f\u0442\u0438 \u043f\u043e\u0437\u043d\u0430\u0447\u043a\u0443 \u0437\u043e\u0432\u0441\u0456\u043c. \u0421\u0432\u0430\u0439\u043f \u043b\u0456\u0432\u043e\u0440\u0443\u0447 \u2014 \u0432\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0437\u0456 \u0441\u043f\u0438\u0441\u043a\u0443."},
gO4(){return"\u041f\u043e\u0445\u0456\u0434 \u0443 \u043c\u0430\u0433\u0430\u0437\u0438\u043d"},
gO3(){return"\u0420\u0435\u0436\u0438\u043c \xab\u0423 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0456\xbb \u043f\u043e\u043a\u0430\u0437\u0443\u0454 \u043b\u0438\u0448\u0435 \u0441\u044c\u043e\u0433\u043e\u0434\u043d\u0456\u0448\u043d\u0456 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u2014 \u0432\u0435\u043b\u0438\u043a\u0438\u043c \u0448\u0440\u0438\u0444\u0442\u043e\u043c, \u0456 \u0435\u043a\u0440\u0430\u043d \u043d\u0435 \u0433\u0430\u0441\u043d\u0435. \u041f\u0456\u0441\u043b\u044f \u043a\u0430\u0441\u0438 \u0442\u0438\u0441\u043d\u0456\u0442\u044c \xab\u041d\u043e\u0432\u0438\u0439 \u043f\u043e\u0445\u0456\u0434\xbb: \u043a\u0443\u043f\u043b\u0435\u043d\u0435 \u043f\u0456\u0434\u0435 \u0432 \u0456\u0441\u0442\u043e\u0440\u0456\u044e \u0437 \u0447\u0435\u043a\u0430\u043c\u0438 \u0442\u0430 \u0430\u043d\u0430\u043b\u0456\u0442\u0438\u043a\u043e\u044e \u0432\u0438\u0442\u0440\u0430\u0442."},
gO6(){return"\u0412\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u0437\u0430 2 \u0441\u0435\u043a\u0443\u043d\u0434\u0438"},
gO5(){return"\u041f\u043e\u0447\u043d\u0456\u0442\u044c \u0434\u0440\u0443\u043a\u0443\u0432\u0430\u0442\u0438 \u2014 \u043f\u0456\u0434\u043a\u0430\u0437\u043a\u0438 \u0441\u0430\u043c\u0456 \u043f\u0456\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u044e \u0442\u0430 \u0456\u043a\u043e\u043d\u043a\u0443. \u041c\u043e\u0436\u043d\u0430 \u0433\u043e\u043b\u043e\u0441\u043e\u043c, \u0444\u043e\u0442\u043e, \u0437\u0430 \u0448\u0442\u0440\u0438\u0445-\u043a\u043e\u0434\u043e\u043c. \u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0442\u0435 \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0438 Mercadona \u0456 Lidl \u2014 \u0431\u0443\u0434\u0443\u0442\u044c \u0446\u0456\u043d\u0438 \u0442\u0430 \u0444\u043e\u0442\u043e \u0442\u043e\u0432\u0430\u0440\u0456\u0432."},
gO8(){return"\u0421\u043f\u0438\u0441\u043a\u0438 \u043d\u0430 \u0434\u0432\u043e\u0445"},
gO7(){return"\u041f\u043e\u0434\u0456\u043b\u0456\u0442\u044c\u0441\u044f \u0441\u043f\u0438\u0441\u043a\u043e\u043c 6-\u0437\u043d\u0430\u0447\u043d\u0438\u043c \u043a\u043e\u0434\u043e\u043c \u2014 \u0437\u043c\u0456\u043d\u0438 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0456\u0437\u0443\u044e\u0442\u044c\u0441\u044f \u043c\u0438\u0442\u0442\u0454\u0432\u043e. \u0412\u0438\u0434\u043d\u043e, \u0445\u0442\u043e \u0437\u0430\u0440\u0430\u0437 \u043f\u0435\u0440\u0435\u0433\u043b\u044f\u0434\u0430\u0454 \u0441\u043f\u0438\u0441\u043e\u043a \u0456 \u0445\u0442\u043e \u0449\u043e \u043a\u0443\u043f\u0438\u0432. \u0412\u0456\u0434\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0439\u0442\u0435\u0441\u044f, \u0449\u043e\u0431 \u0432\u0430\u0441 \u0443\u043f\u0456\u0437\u043d\u0430\u0432\u0430\u043b\u0438:"},
gD2(){return"\u0417\u0440\u043e\u0437\u0443\u043c\u0456\u043b\u043e"},
gKV(){return"\u0421\u0442\u0432\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043d\u043e\u043f\u043a\u043e\u044e \xab+\xbb. \u041e\u0431\u0435\u0440\u0456\u0442\u044c \u0442\u0438\u043f \u2014 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0438, \u0430\u043f\u0442\u0435\u043a\u0430, \u0433\u043e\u0441\u043f\u043e\u0434\u0430\u0440\u0441\u0442\u0432\u043e\u2026 \u2014 \u0443 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0441\u0432\u043e\u0457 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u0457 \u0442\u0430 \u043f\u0456\u0434\u043a\u0430\u0437\u043a\u0438."},
